questionvariables.text:
stack_include_contrib("prooflib.mac");

/* Randomise: b is even (keeps things integer), c chosen so qval = c - (b/2)^2 > 0 */
b: 2*rand_with_step(1, 5, 1) * (2*rand(2)-1);
half_b: b/2;
bsq: half_b^2;
/* Ensure minimum value is positive so "minimum is qval" is non-trivial */
qval: rand_with_step(1, 8, 1);
c: qval + bsq;

/* Pre-render expressions with tex1 so signs are handled properly */
quad_expr: x^2 + b*x + c;
csq_expr: (x + half_b)^2 + qval;
csq_inner: (x + half_b)^2;

/* Use tex1 on whole expressions to get correct sign handling */
t_quad: tex1(quad_expr);
t_csq: tex1(csq_expr);
t_csq_inner: tex1(csq_inner);
t_expand: tex1(x^2 + b*x);
t_step1: tex1((x + half_b)^2 - bsq);

proof_steps: [
    ["half",       sconcat("Half the coefficient of \\(x\\) is \\(", tex1(half_b), "\\).")],
    ["ctsq",       sconcat("So \\(", t_expand, " = ", t_step1, "\\).")],
    ["bring_c",    sconcat("Therefore \\(", t_quad, " = ", t_step1, " + ", tex1(c), " = ", t_csq, "\\).")],
    ["sq_geq",     sconcat("Since \\(", t_csq_inner, " \\geq 0\\) for all \\(x\\), the expression is always at least \\(", tex1(qval), "\\).")],
    ["min_val",    sconcat("Hence the minimum value of \\(", t_quad, "\\) is \\(", tex1(qval), "\\).")],
    ["min_at",     sconcat("This minimum occurs when \\(x = ", tex1(-half_b), "\\).")],
    ["dist1",      sconcat("Half the coefficient of \\(x\\) is \\(", tex1(-half_b), "\\).")],
    ["dist2",      sconcat("Since \\(", t_csq_inner, " > 0\\) for all \\(x\\), the expression is always greater than \\(", tex1(qval), "\\).")]
];

proof_steps: random_permutation(proof_steps);

ta: proof("half", "ctsq", "bring_c", "sq_geq", "min_val", "min_at");
